const content = ($json.content || []).filter(b => b.type === 'text').map(b => b.text).join('\n');
const clean = content.replace(/```json|```/g, '').trim();
let parsed;
try { parsed = JSON.parse(clean); }
catch (e) { throw new Error('La IA no devolvió JSON válido: ' + clean.slice(0, 300)); }
const TAREAS = ['VFX','Color','DG','Motion Graphics','IA','3D/CGI','Retoque','SFX/Mezcla','Online'];
parsed.tareas = (parsed.tareas || []).filter(t => TAREAS.includes(t));
parsed.timeline = (parsed.timeline || []).map(t => ({ fase: t.fase || '', inicio: t.inicio || '', fin: t.fin || '', notas: t.notas || '' }));
parsed.nombre = parsed.nombre || '';
parsed.cliente = parsed.cliente || '';
parsed.agencia = parsed.agencia || '';
parsed.productora = parsed.productora || '';
parsed.director = parsed.director || '';
parsed.sintesis = parsed.sintesis || '';
parsed.storyboard_url = parsed.storyboard_url || '';
return [{ json: parsed }];

const w = $('Webhook').first().json;
const b = w.body;
let texto = '';
if (b && typeof b === 'object') texto = b.debrief_text || b.texto || '';
else if (typeof b === 'string') { try { texto = JSON.parse(b).debrief_text || ''; } catch(e) { texto = b; } }
texto = String(texto || '').trim();
if (!texto) throw new Error('El debrief llegó vacío al workflow. Body recibido: ' + JSON.stringify(b).slice(0, 200));
return [{ json: { texto } }];
